const NZ=[5,6,5,6,6,6,5,7];const Z=[0];NZ.forEach(n=>Z.push(Z[Z.length-1]+n*480+200));const W1=Z[8];
const LX=[];NZ.forEach((n,z)=>{for(let j=0;j<n;j++)LX.push(Z[z]+380+j*480)});LX[45]=W1-130;
