 if(st==5){if(r>.75){palma(g,x+w*.5,gt+8,1.2,TT);return}const hh=110+r*50;rect(g,'#c0a070',x+4,gt-hh,w-20,hh+6);rect(g,'#2a56b0',x+4,gt-hh+16,w-20,12);for(let q=0;q<8;q++)poly(g,'#e0b84a',[[x+8+q*20,gt-hh+18],[x+14+q*20,gt-hh+18],[x+11+q*20,gt-hh+26]]);for(let q=0;q<7;q++)rect(g,'#c0a070',x+4+q*24,gt-hh-10,14,10);return}
 if(st==6){if(r>.7){ulv(g,x+w*.5,gt+8,1.3,TT);return}if(r>.45){g.fillStyle='#9a8e78';g.beginPath();g.ellipse(x+60,gt+6,70,50+r*60,0,Math.PI,0);g.fill();return}
  rect(g,'#8a6a44',x+10,gt-2,w-40,6);for(let q=0;q<5;q++)rect(g,'#3a2a1c',x+14+q*30,gt+2,4,22);poly(g,'#e8e0cc',[[x+14,gt-6],[x+w*.4,gt-60],[x+w-40,gt-6]]);return}
 if(st==7){if(r>.7){ulv(g,x+w*.5,gt+8,1.4,TT);return}const hh=60+r*40;rect(g,'#f0e8d4',x+10,gt-hh,w-50,hh+6);poly(g,'#b4583a',[[x+4,gt-hh],[x+(w-50)/2+10,gt-hh-26],[x+w-34,gt-hh]]);arc(g,'#2a1810',x+w*.35,gt+6,22,36);win(x+w*.6,gt-hh+14);return}
