  if(z[3]=='l'){const bw=zi==1?84:70;for(let r=0;r<5;r++){const yy=gt+7+r*28,s0=Math.floor((cam+x0)/bw)*bw;for(let k=-1;k<Math.ceil(ww/bw)+2;k++){const px=s0+k*bw-cam+(r%2)*bw/2,hh=hr(k*17+r*7);rect(g,hh>.6?'rgba(255,255,255,.1)':hh>.3?'rgba(0,0,0,.08)':'rgba(255,255,255,.03)',px,yy,bw-2,26);rect(g,'rgba(0,0,0,.25)',px+bw-2,yy,2,26)}}}
